from bioblend.galaxy import GalaxyInstance
import time

gi = GalaxyInstance(url='https://usegalaxy.org', key='[REDACTED_GALAXY_API_KEY]')
NEW_HIST_ID = 'bbd44e69cb8906b55c0d3324fe3d23de'

# Try different input path syntaxes
reps = [
    {
        "id_suffix": "dollar-nobraces",
        "shell_command": 'set -eu\nwc -l $counts_raw > output.txt',
    },
    {
        "id_suffix": "dollar-braces",
        "shell_command": 'set -eu\nwc -l ${counts_raw} > output.txt',
    },
    {
        "id_suffix": "on-input-path",
        "shell_command": 'set -eu\nwc -l $on_input_dataset_path > output.txt',
    },
    {
        "id_suffix": "no-template",
        "shell_command": 'set -eu\ncp $__tool_directory__/../inputs/counts_raw output.txt 2>/dev/null || echo "failed" > output.txt',
    },
]

for idx, rep_extra in enumerate(reps):
    rep = {
        "class": "GalaxyUserTool",
        "id": f"test-tmpl-{rep_extra['id_suffix']}-v1",
        "name": f"Test Template {rep_extra['id_suffix']}",
        "version": "0.1.0",
        "container": "quay.io/biocontainers/pydeseq2:0.5.4--pyhdfd78af_0",
        "shell_command": rep_extra['shell_command'],
        "inputs": [
            {"name": "counts_raw", "type": "data", "format": ["csv", "txt", "tabular"]}
        ],
        "outputs": [
            {"name": "output", "type": "data", "format": "txt", "from_work_dir": "output.txt"}
        ],
    }

    try:
        created = gi.unprivileged_tools.create_user_tool(rep)
        uuid = created['uuid']

        submitted = gi.tools.run_tool(
            history_id=NEW_HIST_ID,
            tool_uuid=uuid,
            tool_inputs={
                'counts_raw': {'src': 'hda', 'id': 'f9cad7b01a47213593e04f0ab81f9a1f'}
            },
        )
        jobs = submitted.get('jobs', [])
        if jobs:
            time.sleep(3)
            job = gi.jobs.show_job(jobs[0]['id'], full_details=True)
            print(f"{rep_extra['id_suffix']}: state={job['state']}, cmd={'YES' if job.get('command_line') else 'NONE'}")
            if job.get('command_line'):
                print(f"  CMD: {job['command_line'][:200]}")
            if job.get('stderr'):
                print(f"  STDERR: {job['stderr'][:200]}")
    except Exception as e:
        print(f"{rep_extra['id_suffix']}: ERROR: {e}")

    time.sleep(1)
PYEOF

