from bioblend.galaxy import GalaxyInstance
import time

gi = GalaxyInstance(url='https://usegalaxy.org', key='[REDACTED_GALAXY_API_KEY]')
NEW_HIST_ID = 'bbd44e69cb8906b55c0d3324fe3d23de'

# Try different path syntaxes
tests = [
    ("inputs-dot-path", 'set -eu\nwc -l $inputs.counts_raw > output.txt'),
    ("inputs-bracket-path", 'set -eu\nwc -l $inputs["counts_raw"] > output.txt'),
    ("inputs-dot-input-dot-path", 'set -eu\nwc -l $inputs.input.path > output.txt'),
    ("env-var", 'set -eu\necho "INPUT=$COUNT_RAW" > output.txt\nls -la /galaxy/server/ > output.txt'),
    ("cat-input", 'set -eu\ncat "$counts_raw" | wc -l > output.txt'),
]

for name, shell_cmd in tests:
    rep = {
        "class": "GalaxyUserTool",
        "id": f"test-path-{name}-v1",
        "name": f"Test Path {name}",
        "version": "0.1.0",
        "container": "quay.io/biocontainers/pydeseq2:0.5.4--pyhdfd78af_0",
        "shell_command": shell_cmd,
        "inputs": [
            {"name": "counts_raw", "type": "data", "format": ["csv", "txt", "tabular"]}
        ],
        "outputs": [
            {"name": "output", "type": "data", "format": "txt", "from_work_dir": "output.txt"}
        ],
    }

    try:
        created = gi.unprivileged_tools.create_user_tool(rep)
        uuid = created['uuid']

        submitted = gi.tools.run_tool(
            history_id=NEW_HIST_ID,
            tool_uuid=uuid,
            tool_inputs={
                'counts_raw': {'src': 'hda', 'id': 'f9cad7b01a47213593e04f0ab81f9a1f'}
            },
        )
        jobs = submitted.get('jobs', [])
        if jobs:
            time.sleep(5)
            job = gi.jobs.show_job(jobs[0]['id'], full_details=True)
            print(f"{name}: state={job['state']}")
            if job.get('command_line'):
                print(f"  CMD: {job['command_line'][:300]}")
            if job.get('stderr'):
                print(f"  STDERR: {repr(job['stderr'][:300])}")
            if job.get('stdout'):
                print(f"  STDOUT: {repr(job['stdout'][:300])}")
    except Exception as e:
        print(f"{name}: ERROR: {e}")

    time.sleep(1)
PYEOF

